mapper.update:
update photoinfo
set photo_url=#{photoUrl},
    tag_id=#{tagId},
    user_id=#{userId},
    fingerprint=#{fingerprint},
    title=#{title}
where file_path = #{filePath}
  and id = #{id}

mapper.select:
select v.* from ( select t1.*,t2.id as tagId,t2.name as tagName from photoinfo t1,tag t2 where t1.tag_id=t2.id)v where 1=1
and v.title like CONCAT('%',#{param1},'%')
and v.tagId=#{param2}
